function inverterString(str) {
  return str.split('').reverse().join('');
}

// Exportando a função para uso em outros módulos (CommonJS)
module.exports = inverterString;

// Exemplo de uso (pode ser removido se preferir)
if (require.main === module) {
  console.log(inverterString("JavaScript")); // tpircSavaJ
  console.log(inverterString("hello"));      // olleh
  console.log(inverterString(""));           // (string vazia)
  console.log(inverterString("a"));          // a
}
```

**Como funciona:**

A função `inverterString` recebe uma string e aplica três métodos em sequência:

1. **`split('')`** — converte a string em um array de caracteres.
2. **`reverse()`** — inverte a ordem dos elementos do array.
3. **`join('')`** — junta os caracteres novamente em uma string.

