# `contador_cliques.js`

```javascript
// contador_cliques.js
// Conta quantas vezes um botão foi clicado e exibe o total na tela.

document.addEventListener('DOMContentLoaded', () => {
  // Estado da contagem
  let contador = 0;

  // Criação dos elementos
  const container = document.createElement('div');
  const botao = document.createElement('button');
  const display = document.createElement('p');

  // Conteúdo inicial
  botao.textContent = 'Clique aqui';
  display.textContent = `Cliques: ${contador}`;

  // Estilização inline (para funcionar sem CSS externo)
  container.style.cssText = `
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    font-family: Arial, sans-serif;
    margin-top: 40px;
  `;

  botao.style.cssText = `
    padding: 12px 24px;
    font-size: 16px;
    cursor: pointer;
    border: none;
    border-radius: 6px;
    background-color: #4a90e2;
    color: #fff;
    transition: background-color 0.2s;
  `;

  botao.addEventListener('mouseenter', () => {
    botao.style.backgroundColor = '#357ab8';
  });
  botao.addEventListener('mouseleave', () => {
    botao.style.backgroundColor = '#4a90e2';
  });

  display.style.cssText = `
    margin-top: 16px;
    font-size: 18px;
    color: #333;
  `;

  // Evento de clique: incrementa o contador e atualiza o display
  botao.addEventListener('click', () => {
    contador++;
    display.textContent = `Cliques: ${contador}`;
  });

  // Montagem na página
  container.appendChild(botao);
  container.appendChild(display);
  document.body.appendChild(container);
});
```

