    scanf("%d %d %d %d %d", &n1, &n2, &n3, &n4, &n5);

    soma = n1 + n2 + n3 + n4 + n5;

    printf("A soma dos 5 numeros e: %d\n", soma);

    return 0;
}
```

A versão com `for` é mais recomendada, pois é escalável — caso seja necessário ler 100 ou 1000 números, basta alterar a condição do loop.

